import { useState } from "react";
import "./styles/AdminU.css"; // Asegúrate de tener los estilos adecuados
import { useNavigate } from "react-router-dom";

function AdminU({ locations, user, onBack }) {
  const [showEditModal, setShowEditModal] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [buildingList, setBuildingList] = useState(locations.buildings || []);
  const [classroomList, setClassroomList] = useState([]);
  const [laboratoryList, setLaboratoryList] = useState([]);
  const navigate = useNavigate();

  const handleEditClick = (item, type) => {
    setEditingItem({ ...item, type });
    setShowEditModal(true);
  };

  const handleCloseModal = () => {
    setShowEditModal(false);
    setEditingItem(null);
  };

  const handleSaveItem = (e) => {
    e.preventDefault();
    if (editingItem.type === "building") {
      setBuildingList(
        buildingList.map((b) =>
          b.id === editingItem.id ? editingItem : b
        )
      );
    } else if (editingItem.type === "classroom") {
      setClassroomList(
        classroomList.map((c) =>
          c.id === editingItem.id ? editingItem : c
        )
      );
    } else if (editingItem.type === "laboratory") {
      setLaboratoryList(
        laboratoryList.map((l) =>
          l.id === editingItem.id ? editingItem : l
        )
      );
    }
    handleCloseModal();
  };

  const handleDeleteItem = (id, type) => {
    if (type === "building") {
      setBuildingList(buildingList.filter((b) => b.id !== id));
    } else if (type === "classroom") {
      setClassroomList(classroomList.filter((c) => c.id !== id));
    } else if (type === "laboratory") {
      setLaboratoryList(laboratoryList.filter((l) => l.id !== id));
    }
  };

  const handleAddItem = (type) => {
    const newItem = {
      id: Date.now(), // Utiliza la hora actual para un ID único
      name: "",
      description: "",
      location: "",
      capacity: "",
      type,
    };
    setEditingItem(newItem);
    setShowEditModal(true);
  };

  const handleBack = () => {
    navigate(-1); // Regresa a la página anterior
  };

  return (
    <div className="adminU-container">
      {/* Header */}
      <header className="adminU-header">
        <div className="adminU-header-left">
          {/* Botón de regresar */}
          <button className="adminU-back-btn" onClick={handleBack} title="Volver">
            <i className="bi bi-chevron-double-left"></i>
          </button>
          <h1 className="adminU-title">TalkinPon</h1>
        </div>

        {/* Icono de usuario */}
        <div className="adminU-user-icon-container">
          <i className="bi bi-person-circle user-icon"></i>
          <h5>{user.role}</h5>
        </div>
      </header>

      {/* Main */}
      <main className="adminU-main">
        {/* Edificios */}
        <div className="adminU-section">
          <h2 className="adminU-section-header">Gestión de Edificios</h2>

          <table className="adminU-table">
            <thead>
              <tr>
                <th>Nombre</th>
                <th>Descripción</th>
                <th>Ubicación</th>
                <th>Capacidad</th>
                <th>Opciones</th>
              </tr>
            </thead>
            <tbody>
              {buildingList.map((building) => (
                <tr key={building.id}>
                  <td>{building.name}</td>
                  <td>{building.description}</td>
                  <td>{building.location}</td>
                  <td>{building.capacity}</td>
                  <td>
                    <button
                      className="adminU-option-btn edit"
                      onClick={() => handleEditClick(building, "building")}
                      title="Editar"
                    >
                      <i className="bi bi-pencil-fill"></i>
                    </button>
                    <button
                      className="adminU-option-btn delete"
                      onClick={() => handleDeleteItem(building.id, "building")}
                      title="Eliminar"
                    >
                      <i className="bi bi-trash-fill"></i>
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="adminU-add-user-container">
            <button className="adminU-add-user-btn" onClick={() => handleAddItem("building")}>
              Agregar nuevo edificio
            </button>
          </div>
        </div>

        {/* Salones */}
        <div className="adminU-section">
          <h2 className="adminU-section-header">Gestión de Salones</h2>

          <table className="adminU-table">
            <thead>
              <tr>
                <th>Nombre</th>
                <th>Descripción</th>
                <th>Ubicación</th>
                <th>Capacidad</th>
                <th>Opciones</th>
              </tr>
            </thead>
            <tbody>
              {classroomList.map((classroom) => (
                <tr key={classroom.id}>
                  <td>{classroom.name}</td>
                  <td>{classroom.description}</td>
                  <td>{classroom.location}</td>
                  <td>{classroom.capacity}</td>
                  <td>
                    <button
                      className="adminU-option-btn edit"
                      onClick={() => handleEditClick(classroom, "classroom")}
                      title="Editar"
                    >
                      <i className="bi bi-pencil-fill"></i>
                    </button>
                    <button
                      className="adminU-option-btn delete"
                      onClick={() => handleDeleteItem(classroom.id, "classroom")}
                      title="Eliminar"
                    >
                      <i className="bi bi-trash-fill"></i>
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="adminU-add-user-container">
            <button className="adminU-add-user-btn" onClick={() => handleAddItem("classroom")}>
              Agregar nuevo salón
            </button>
          </div>
        </div>

        {/* Laboratorios */}
        <div className="adminU-section">
          <h2 className="adminU-section-header">Gestión de Laboratorios</h2>

          <table className="adminU-table">
            <thead>
              <tr>
                <th>Nombre</th>
                <th>Descripción</th>
                <th>Ubicación</th>
                <th>Capacidad</th>
                <th>Opciones</th>
              </tr>
            </thead>
            <tbody>
              {laboratoryList.map((laboratory) => (
                <tr key={laboratory.id}>
                  <td>{laboratory.name}</td>
                  <td>{laboratory.description}</td>
                  <td>{laboratory.location}</td>
                  <td>{laboratory.capacity}</td>
                  <td>
                    <button
                      className="adminU-option-btn edit"
                      onClick={() => handleEditClick(laboratory, "laboratory")}
                      title="Editar"
                    >
                      <i className="bi bi-pencil-fill"></i>
                    </button>
                    <button
                      className="adminU-option-btn delete"
                      onClick={() => handleDeleteItem(laboratory.id, "laboratory")}
                      title="Eliminar"
                    >
                      <i className="bi bi-trash-fill"></i>
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="adminU-add-user-container">
            <button className="adminU-add-user-btn" onClick={() => handleAddItem("laboratory")}>
              Agregar nuevo laboratorio
            </button>
          </div>
        </div>
      </main>

      {/* Modal para Editar */}
      {showEditModal && editingItem && (
        <div className="adminU-modal-overlay" onClick={handleCloseModal}>
          <div className="adminU-modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="adminU-modal-header">
              <h2>{editingItem.name ? "Editar " : "Agregar "} {editingItem.type}</h2>
              <button className="adminU-modal-close" onClick={handleCloseModal}>
                ✕
              </button>
            </div>
            <form className="adminU-edit-form" onSubmit={handleSaveItem}>
              <div className="adminU-form-group">
                <label>Nombre:</label>
                <input
                  type="text"
                  value={editingItem.name}
                  onChange={(e) => setEditingItem({ ...editingItem, name: e.target.value })}
                  placeholder="Nombre"
                  required
                />
              </div>
              <div className="adminU-form-group">
                <label>Descripción:</label>
                <input
                  type="text"
                  value={editingItem.description}
                  onChange={(e) => setEditingItem({ ...editingItem, description: e.target.value })}
                  placeholder="Descripción"
                  required
                />
              </div>
              <div className="adminU-form-group">
                <label>Ubicación:</label>
                <input
                  type="text"
                  value={editingItem.location}
                  onChange={(e) => setEditingItem({ ...editingItem, location: e.target.value })}
                  placeholder="Ubicación"
                  required
                />
              </div>
              <div className="adminU-form-group">
                <label>Capacidad:</label>
                <input
                  type="number"
                  value={editingItem.capacity}
                  onChange={(e) => setEditingItem({ ...editingItem, capacity: e.target.value })}
                  placeholder="Capacidad"
                  required
                />
              </div>
              <div className="adminU-form-actions">
                <button type="button" className="adminU-btn-cancel" onClick={handleCloseModal}>
                  Cancelar
                </button>
                <button type="submit" className="adminU-btn-save">
                  Guardar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default AdminU;
